		}
		seen.set(name, attribute);
	}
}

function collectSpreadAttribute(
	attribute: AnyNode,
	state: WalkState,
	walk: SemanticGraphWalk,
	hostNodeId: string | null,
): void {
	const argument = attribute.argument as AnyNode | undefined;
	if (!argument) return;
	if (!hostNodeId) {
		walk(argument, state);
		return;
	}

	const spreadSource = expressionSource(argument, state.source);
	const objectKeys = staticObjectKeys(resolveStaticObjectExpression(argument, state));
	const eventKeys = objectKeys.filter(isSpreadEventKey);
	if (eventKeys.length > 0) {
		state.graph.diagnostics.push(
			eventSpreadUnsupportedDiagnostic({
				spreadSource,
				keys: eventKeys,
				node: argument,
				filename: state.filename,
			}),
		);
		walk(argument, state);
		return;
	}

	// Separate from isSpreadEventKey on purpose: that key set feeds an
	// event-specific diagnostic. A spread can never carry overlay, because the
	// mark has to be readable as a literal on the element itself.
	if (objectKeys.includes('overlay')) {
		state.graph.diagnostics.push(
			overlayValueUnsupportedDiagnostic({
				source: spreadSource,
				carrier: 'spread',
				span: sourceSpan(argument, state.filename),
			}),
		);
		walk(argument, state);
		return;
	}

	const resolved = resolveGraphPath(
		spreadSource,
		graphBindingMap(state.graph),
		semanticAliasMap(state.graph),
	);
	if (resolved?.binding.kind === 'state' || resolved?.binding.kind === 'computed') {
		state.graph.diagnostics.push(
			spreadStaticSnapshotDiagnostic({
				spreadSource,
				node: argument,
				filename: state.filename,
			}),
		);
	}
	walk(argument, state);
}

function attributeValueDiagnostic(
	attributeName: string,
	expressionValue: AnyNode,
	state: WalkState,
): SemanticGraphDiagnostic | null {
	const valueSource = expressionSource(expressionValue, state.source);
	if (isLowercaseEventAttributeName(attributeName) && isFunctionExpressionLike(expressionValue)) {
		return attributeObjectValueDiagnostic({
			attributeName,
			valueSource,
			node: expressionValue,
			filename: state.filename,
			eventSuggestion: eventAttributeSuggestion(attributeName),
		});
	}

	const resolved = resolveGraphPath(
		valueSource,
		graphBindingMap(state.graph),
		semanticAliasMap(state.graph),
	);
	const isObjectValue =
		expressionValue.type === 'ObjectExpression' ||
		expressionValue.type === 'ArrayExpression' ||
		(resolved?.path.length === 0 &&
			(resolved.binding.valueKind === 'object' || resolved.binding.valueKind === 'array'));
	if (!isObjectValue) return null;
	if (attributeName === 'style') {
		return styleObjectUnsupportedDiagnostic({
			valueSource,
			node: expressionValue,
			filename: state.filename,
		});
	}
	return attributeObjectValueDiagnostic({
		attributeName,
		valueSource,
		node: expressionValue,
		filename: state.filename,
	});
}

function resolvePropForwardedElementHandle(
	binding: SemanticElementHandleBinding,
	resolved: {
		readonly binding: SemanticGraphBinding;
		readonly path: ReadonlyArray<string>;
	},
	graph: MutableSemanticGraphArtifact,
): { readonly name: string } | null {
	if (resolved.binding.kind !== 'prop' || !binding.componentName) return null;

	const propName = resolved.path[0];
	if (!propName || resolved.path.length !== 1) return null;

	const edgeProp = graph.componentEdges
		.filter((edge) => edge.childComponentName === binding.componentName)
		.flatMap((edge) => edge.props)
		.find(
			(prop): prop is Extract<SemanticComponentPropBinding, { kind: 'graph-reference' }> =>
				prop.name === propName &&
				prop.kind === 'graph-reference' &&
				prop.graphBindingKind === 'element' &&
				prop.path.length === 0,
		);
	if (!edgeProp) return null;

	const handle = graph.graphBindings.find(
		(graphBinding) => graphBinding.id === edgeProp.graphNodeId,
	);
	if (!handle || handle.kind !== 'element') return null;

	return { name: handle.name };
}

type IdrefValueClassification =
	| { readonly kind: 'handle'; readonly handleName: string }
	| { readonly kind: 'composite' };

/**
 * Classifies an IDREF attribute value. `handle` is one element() handle written
 * directly, the only form this slice records. `composite` is any expression that
 * mentions a handle without being one - a list, a join, a choice - which is
 * refused rather than lowered. `null` is everything else, including an ordinary
 * id string, which keeps its existing templateRead.
 */
function classifyIdrefValue(
	expression: AnyNode,
	state: WalkState,
): IdrefValueClassification | null {
	const handleName = resolvedElementHandleName(expression, state);
	if (handleName) return { kind: 'handle', handleName };
	return mentionsElementHandle(expression, state) ? { kind: 'composite' } : null;
}

function resolvedElementHandleName(expression: AnyNode, state: WalkState): string | null {
	const source = expressionSource(expression, state.source);
	if (!source) return null;
	const resolved = resolveGraphPath(
		source,
		graphBindingMap(state.graph),
		semanticAliasMap(state.graph),
	);
	// A member path such as `label.id` is a render-time DOM read, not identity;
	// it keeps falling through to MARKLESS_ELEMENT_HANDLE_RENDER_READ.
	if (!resolved || resolved.binding.kind !== 'element' || resolved.path.length > 0) return null;
	return resolved.binding.name;
}

function mentionsElementHandle(expression: AnyNode, state: WalkState): boolean {
	let found = false;
	walkNode(expression, (node) => {
		if (found || node.type !== 'Identifier') return;
		if (resolvedElementHandleName(node, state)) found = true;
	});
	return found;
}

function conditionalClassTarget(
	attributeName: string,
	expressionValue: AnyNode | undefined,
): {
	readonly test: AnyNode;
	readonly target: SemanticTemplateBindingTarget;
} | null {
	if (attributeName !== 'class' || expressionValue?.type !== 'ConditionalExpression') {
		return null;
	}

	const test = expressionValue.test as AnyNode | undefined;
	const trueValue = stringLiteral(expressionValue.consequent as AnyNode | undefined);
	const falseValue = stringLiteral(expressionValue.alternate as AnyNode | undefined);
	if (!test || trueValue === null || falseValue === null) return null;

	return {
		test,
		target: {
			kind: 'class',
			trueValue,
			falseValue,
		},
	};
}

function stringLiteral(node: AnyNode | undefined): string | null {
	return node?.type === 'Literal' && typeof node.value === 'string' ? node.value : null;
}

function sameHostStaticTextBranch(
	node: AnyNode | undefined,
	state: WalkState,
): {
	readonly hostNodeId: string;
	readonly tagName: string;
	readonly staticAttributesKey: string;
	readonly text: string;
} | null {
	const root = branchSingleOutput(node);
	if (!root || (root.type !== 'Element' && root.type !== 'JSXElement')) return null;

	const tagName = getElementTagName(root);
	if (!tagName || !isHostTagName(tagName)) return null;

	const hostNodeId = state.hostIds.get(root);
	const text = singleStaticTextChild(root);
	const staticAttributesKey = staticAttributeKey(root);
	if (!hostNodeId || text === null || staticAttributesKey === null) return null;

	return {
		hostNodeId,
		tagName,
		staticAttributesKey,
		text,
	};
}

function branchSingleOutput(node: AnyNode | undefined): AnyNode | null {
	if (!node) return null;
	if (node.type === 'BlockStatement') {
		const outputs = asNodes(node.body).filter((child) => !isIgnorableJsxTextNode(child));
		return outputs.length === 1 ? branchSingleOutput(outputs[0]) : null;
	}
	if (node.type === 'ExpressionStatement') {
		return branchSingleOutput(node.expression as AnyNode | undefined);
	}
	return node;
}

function singleStaticTextChild(node: AnyNode): string | null {
	const children = asNodes(node.children).filter((child) => !isIgnorableJsxTextNode(child));
	if (children.length !== 1) return null;
	const child = children[0]!;
	const text = trimmedStaticTextValue(child);
	return text === '' ? null : text;
}

// The whole value grammar for overlay: bare (true), {true}, {false}. Anything
// else - identifier, member access, call, template, non-boolean literal - is a
// null return, which the caller turns into MARKLESS_OVERLAY_VALUE_UNSUPPORTED.
function overlayLiteralValue(
	value: AnyNode | undefined,
	expression: AnyNode | undefined,
): boolean | null {
	if (!value) return true;
	const literal = expression ?? value;
	if (literal.type === 'Literal' && typeof literal.value === 'boolean') return literal.value;
	return null;
}

// No overlay case here on purpose: bare `overlay` already keys as
// ["overlay","true"] via the !value branch, and overlay={true} keys identically
// via the expression branch, so @if arm merging already treats the two spellings
// as the same arm shape. Skipping overlay would instead merge an elevated arm
// with a non-elevated one.
function staticAttributeKey(node: AnyNode): string | null {
	const attributes: Array<readonly [string, string]> = [];
	for (const attribute of getElementAttributes(node)) {
		const name = getIdentifierName(attribute.name as AnyNode | undefined);
		if (!name || isEventAttribute(name) || name === 'attach' || name === 'el') return null;

		const value = attribute.value as AnyNode | undefined;
		const expression = unwrapExpressionContainer(value);
		if (!value) {
			attributes.push([name, 'true']);
			continue;
		}
		if (value.type === 'Literal' && typeof value.value !== 'object') {
			attributes.push([name, String(value.value)]);
			continue;
		}
		if (expression?.type === 'Literal' && typeof expression.value !== 'object') {
			attributes.push([name, String(expression.value)]);
			continue;
		}
		return null;
	}
	return JSON.stringify(attributes);
}

function bindingTargetForAttribute(attributeName: string): SemanticTemplateBindingTarget {
	if (attributeName === 'class') return { kind: 'class' };
	if (attributeName === 'style') return { kind: 'style' };

	if (isDomPropertyBindingName(attributeName)) {
		return {
			kind: 'property',
			name: attributeName,
		};
	}

	return {
		kind: 'attribute',
		name: attributeName,
	};
}

function isDomPropertyBindingName(attributeName: string): boolean {
	return attributeName === 'value' || attributeName === 'checked' || attributeName === 'selected';
}

function resolveStaticObjectExpression(node: AnyNode, state: WalkState): AnyNode | null {
	if (node.type === 'ObjectExpression') return node;
	const name = getIdentifierName(node);
	if (!name) return null;
	let found: AnyNode | null = null;
	const ast = parseModule(state.source, state.filename) as unknown as AnyNode;
	walkNode(ast, (candidate) => {
		if (found || candidate.type !== 'VariableDeclarator') return;
		const id = candidate.id as AnyNode | undefined;
		const init = candidate.init as AnyNode | undefined;
		if (getIdentifierName(id) === name && init?.type === 'ObjectExpression') found = init;
	});
	return found;
}

function staticObjectKeys(node: AnyNode | null): string[] {
	if (!node || node.type !== 'ObjectExpression') return [];
	return asNodes(node.properties).flatMap((property) => {
		if (property.type !== 'Property') return [];
		const key = property.key as AnyNode | undefined;
		const name = getIdentifierName(key);
		if (name) return [name];
		if (key?.type === 'Literal' && typeof key.value === 'string') return [key.value];
		return [];
				projectionChunkId,
				'component-projection',
				builder.componentName,
			);
			emitNodes(projected, [0], projection, context, repeat);
			context.chunks.push(finishChunk(projection));
		}
		addAnchorSlot(
			builder,
			{
				kind: 'child-component',
				componentEdgeId: edge?.id ?? `component-edge:${tagName}:${span?.start ?? 0}`,
				childComponentName: tagName,
				childTemplateId: `template:${tagName}`,
				...(projectionChunkId ? { projectionChunkId } : {}),
			},
			path,
		);
		return 1;
	}
	const hostNodeId = context.hostIds.get(node);
	if (hostNodeId) {
		builder.hosts.push({
			hostNodeId,
			tagName,
			coordinate: { kind: 'child-index', path },
		});
	}

	append(builder, `<${tagName}`);
	let classSeen = false;
	const elementAttributes = getElementAttributes(node);
	const declaredAttributeNames = elementAttributes.flatMap((candidate) => {
		if (isSpreadAttribute(candidate)) return [];
		const name = getIdentifierName(candidate.name as AnyNode | undefined);
		return name ? [name] : [];
	});
	for (const attribute of elementAttributes) {
		if (isSpreadAttribute(attribute)) {
			const expression = unwrapExpressionContainer(
				(attribute.argument ?? attribute.value) as AnyNode | undefined,
			);
			if (expression)
				addSlot(builder, {
					kind: 'spread-attributes',
					coordinate: { kind: 'child-index', path },
					residue: expressionResidue(expression, context, repeat),
					excludeNames: declaredAttributeNames,
				});
			continue;
		}
		const name = getIdentifierName(attribute.name as AnyNode | undefined);
		// overlay is a compiler-side elevation mark, not a DOM attribute: without this
		// skip staticAttributeValue leaks ` overlay=""` (bare) or ` overlay="true"`
		// ({true}) straight into the emitted statics.
		if (
			!name ||
			isEventAttribute(name) ||
			name === 'attach' ||
			name === 'el' ||
			name === 'overlay' ||
			isElementHandleIdref(context, node, name)
		)
			continue;
		if (name === 'class') classSeen = true;
		const value = attribute.value as AnyNode | undefined;
		const expression = unwrapExpressionContainer(value);
		const literal = staticAttributeValue(value, expression);
		if (literal !== null) {
			append(builder, ` ${name}="${escapeAttribute(name === 'class' && context.styleScopeClass ? `${literal} ${context.styleScopeClass}` : literal)}"`);
			continue;
		}
		if (!expression) continue;
		append(builder, ` ${name}="`);
		addSlot(builder, {
			kind: 'attribute',
			name,
			coordinate: { kind: 'child-index', path },
			residue: expressionResidue(expression, context, repeat),
			...(name === 'class' && repeat
				? { directClassMatch: directClassMatch(expression, context, repeat) }
				: {}),
		});
		append(builder, '"');
	}
	if (context.styleScopeClass && !classSeen)
		append(builder, ` class="${context.styleScopeClass}"`);
	append(builder, '>');
	emitNodes(asNodes(node.children), [...path, 0], builder, context, repeat);
	append(builder, `</${tagName}>`);
	return 1;
}

/**
 * An IDREF attribute whose value resolved to an element() handle is a recorded
 * relationship, not a value binding, so it must not reach the statics at all.
 * Emitting the slot anyway would ship `aria-labelledby=""` - an id reference
 * pointing at nothing, which is worse than an absent attribute. The consuming
 * emitter writes both sides of the relationship from the record.
 */
function isElementHandleIdref(context: CollectionContext, node: AnyNode, name: string): boolean {
	if (!isIdrefAttribute(name)) return false;
	const hostNodeId = context.hostIds.get(node);
	if (!hostNodeId) return false;
	return context.graph.elementHandleIdrefs.some(
		(idref) => idref.hostNodeId === hostNodeId && idref.attributeName === name,
	);
}

function directClassMatch(expression: AnyNode,
	context: CollectionContext,
	repeat: { readonly id: string; readonly itemName: string },
) {
	if (expression.type !== 'ConditionalExpression') return undefined;
	const test = expression.test as AnyNode | undefined;
	if (test?.type !== 'BinaryExpression' || (test.operator !== '===' && test.operator !== '==')) {
		return undefined;
	}
	const left = expressionResidue(test.left as AnyNode, context, repeat);
	const right = expressionResidue(test.right as AnyNode, context, repeat);
	const graph = left.kind === 'graph-read' ? left : right.kind === 'graph-read' ? right : null;
	const item = left.kind === 'repeat-item' ? left : right.kind === 'repeat-item' ? right : null;
	const consequent = expression.consequent as AnyNode | undefined;
	const alternate = expression.alternate as AnyNode | undefined;
	if (
		!graph || !item ||
		consequent?.type !== 'Literal' || typeof consequent.value !== 'string' ||
		alternate?.type !== 'Literal' || typeof alternate.value !== 'string'
	) return undefined;
	return {
		stateGraphNodeId: graph.graphNodeId,
		statePath: graph.path,
		itemPath: item.path,
		trueClass: consequent.value,
		falseClass: alternate.value,
	};
}

function emitDynamicHost(
	node: AnyNode,
	tagExpression: AnyNode,
	path: ReadonlyArray<number>,
	builder: ChunkBuilder,
	context: CollectionContext,
	repeat: { readonly id: string; readonly itemName: string } | null,
): void {
	const staticAttributes: Record<string, string> = {};
	const attributeSlots: Array<
		| {
				readonly kind: 'attribute';
				readonly name: string;
				readonly residue: SemanticMarkupResidue;
		  }
		| { readonly kind: 'spread'; readonly residue: SemanticMarkupResidue }
	> = [];
	for (const attribute of getElementAttributes(node)) {
		if (isSpreadAttribute(attribute)) {
			const expression = unwrapExpressionContainer(
				(attribute.argument ?? attribute.value) as AnyNode | undefined,
			);
			if (expression) {
				attributeSlots.push({
					kind: 'spread',
					residue: expressionResidue(expression, context, repeat),
				});
			}
			continue;
		}
		const name = getIdentifierName(attribute.name as AnyNode | undefined);
		// overlay is a compiler-side elevation mark, not a DOM attribute: without this
		// skip staticAttributeValue leaks ` overlay=""` (bare) or ` overlay="true"`
		// ({true}) straight into the emitted statics.
		if (
			!name ||
			isEventAttribute(name) ||
			name === 'attach' ||
			name === 'el' ||
			name === 'overlay' ||
			isElementHandleIdref(context, node, name)
		)
			continue;
		const value = attribute.value as AnyNode | undefined;
		const expression = unwrapExpressionContainer(value);
		const literal = staticAttributeValue(value, expression);
		if (literal !== null) {
			staticAttributes[name] = literal;
			continue;
		}
		if (expression) {
			attributeSlots.push({
				kind: 'attribute',
				name,
				residue: expressionResidue(expression, context, repeat),
			});
		}
	}
	if (context.styleScopeClass) {
		staticAttributes.class = staticAttributes.class
			? `${staticAttributes.class} ${context.styleScopeClass}`
			: context.styleScopeClass;
	}

	const childChunkId = `dynamic-host:${builder.id}:${builder.slots.length}:children`;
	const childBuilder = createChunk(childChunkId, 'dynamic-host-children', builder.componentName);
	emitNodes(asNodes(node.children), [0], childBuilder, context, repeat);
	context.chunks.push(finishChunk(childBuilder));
	const hostNodeId = context.hostIds.get(node);
	if (!hostNodeId) {
		throw new Error(`Semantic markup could not resolve the dynamic host at ${path.join('.')}.`);
	}
	addAnchorSlot(
		builder,
		{
			kind: 'dynamic-host',
			hostNodeId,
			cardinality: 'zero-or-one',
			nullishTag: 'omit',
			tag: expressionResidue(tagExpression, context, repeat),
			staticAttributes,
			attributeSlots,
			childChunkId,
		},
		path,
	);
}

function emitNodes(
	nodes: ReadonlyArray<AnyNode>,
	startPath: ReadonlyArray<number>,
	builder: ChunkBuilder,
	context: CollectionContext,
	repeat: { readonly id: string; readonly itemName: string } | null,
): number {
	const prefix = startPath.slice(0, -1);
	const startIndex = startPath[startPath.length - 1] ?? 0;
	let childIndex = startIndex;
	for (const node of nodes) {
		if (isIgnorableStaticTextNode(node)) continue;
		childIndex += emitNode(node, [...prefix, childIndex], builder, context, repeat);
	}
	return childIndex - startIndex;
import { asNodes, childNodes, isNode, type AnyNode } from '../../ast/nodes.ts';
import { expressionSource, sourceSpan } from '../../ast/source.ts';
import {
	graphBindingMap,
	resolveGraphPath,
	semanticAliasMap,
} from '../../artifact-helpers/graph-paths.ts';
import {
	stateWriteInComputedDiagnostic,
	stateWriteInTemplateDiagnostic,
	templateAsValueDiagnostic,
} from './diagnostics.ts';
import type { DeferredComputedWrite, WalkState } from './types.ts';

export function collectAssignment(node: AnyNode, state: WalkState): void {
	const target = unwrapChainExpression(node.left as AnyNode | undefined);
	if (!target) return;
	const operator = typeof node.operator === 'string' ? node.operator : '=';
	const value = node.right as AnyNode | undefined;
	if (diagnoseBannedWriteSite(node, target, state)) return;

	state.graph.stateWrites.push({
		target: expressionSource(target, state.source),
		...sharedScope(state),
		...writeScope(state),
		targetSpan: sourceSpan(target, state.filename),
		operation: 'assign',
		assignmentOperator: operator === '=' ? undefined : operator,
		valueSource: value ? expressionSource(value, state.source) : undefined,
	});
}

export function collectUpdate(node: AnyNode, state: WalkState): void {
	const target = unwrapChainExpression(node.argument as AnyNode | undefined);
	if (!target) return;
	if (diagnoseBannedWriteSite(node, target, state)) return;

	state.graph.stateWrites.push({
		target: expressionSource(target, state.source),
		...sharedScope(state),
		...writeScope(state),
		targetSpan: sourceSpan(target, state.filename),
		operation: 'update',
		prefix: node.prefix === true,
		updateOperator: node.operator === '--' ? '--' : '++',
	});
}

export function collectCollectionCall(node: AnyNode, state: WalkState): void {
	const callee = unwrapChainExpression(node.callee as AnyNode | undefined);
	if (callee?.type !== 'MemberExpression') return;

	const method = getStaticMemberPropertyName(callee);
	if (!method || !isMutatingCollectionMethod(method)) return;

	const target = unwrapChainExpression(callee.object as AnyNode | undefined);
	if (!target) return;
	if (diagnoseBannedWriteSite(node, target, state)) return;

	for (const argument of asNodes(node.arguments)) {
		const templateValue = findTemplateValue(argument);
		if (!templateValue) continue;
		state.graph.diagnostics.push(
			templateAsValueDiagnostic({
				siteSource: expressionSource(node, state.source),
				node: templateValue,
				filename: state.filename,
			}),
		);
		markTemplateValueHandled(templateValue);
	}

	state.graph.stateWrites.push({
		target: expressionSource(target, state.source),
		...sharedScope(state),
		...writeScope(state),
		targetSpan: sourceSpan(target, state.filename),
		operation: 'call',
		method,
		argumentSources: asNodes(node.arguments).map((argument) =>
			expressionSource(argument, state.source),
		),
		optional:
			node.optional === true || callee.optional === true || isChainExpression(node.callee),
	});
}

const templateValueTypes = new Set([
	'Element',
	'JSXElement',
	'Fragment',
	'JSXFragment',
	'JSXIfExpression',
	'JSXForExpression',
	'JSXSwitchExpression',
	'JSXTryExpression',
]);

export function findTemplateValue(node: AnyNode | undefined): AnyNode | null {
	if (!node) return null;
	if (templateValueTypes.has(node.type ?? '')) return node;
	if (node.type !== 'ArrayExpression') return null;
	for (const element of asNodes(node.elements)) {
		const found = findTemplateValue(element);
		if (found) return found;
	}
	return null;
}

export function markTemplateValueHandled(node: AnyNode): void {
	Object.assign(node, { type: 'MarklessTemplateValue' });
}

export function collectDelete(node: AnyNode, state: WalkState): void {
	if (node.operator !== 'delete') return;

	const originalTarget = node.argument as AnyNode | undefined;
	const target = unwrapChainExpression(originalTarget);
	if (target?.type !== 'MemberExpression') return;
	if (diagnoseBannedWriteSite(node, target, state)) return;

	state.graph.stateWrites.push({
		target: expressionSource(originalTarget ?? target, state.source),
		...sharedScope(state),
		...writeScope(state),
		targetSpan: sourceSpan(originalTarget ?? target, state.filename),
		operation: 'delete',
		optional: target.optional === true || isChainExpression(originalTarget),
	});
}

export function collectExpressionReads(node: AnyNode | undefined, state: WalkState): void {
	if (!node) return;

	if (
		node.type === 'ArrowFunctionExpression' ||
		node.type === 'FunctionExpression' ||
		node.type === 'FunctionDeclaration'
	) {
		const previousShadowedBindings = state.shadowedBindingNames;
		state.shadowedBindingNames = new Set(previousShadowedBindings);
		for (const name of bindingNames(node.id as AnyNode | undefined)) {
			state.shadowedBindingNames.add(name);
		}
		for (const parameter of asNodes(node.params)) {
			for (const name of bindingNames(parameter)) state.shadowedBindingNames.add(name);
		}
		for (const name of functionScopedBindingNames(node.body as AnyNode | undefined)) {
			state.shadowedBindingNames.add(name);
		}
		collectExpressionReads(node.body as AnyNode | undefined, state);
		state.shadowedBindingNames = previousShadowedBindings;
		return;
	}

	if (node.type === 'BlockStatement' || node.type === 'SwitchStatement') {
		withShadowedBindings(state, blockScopedBindingNames(node), () => {
			for (const child of childNodes(node)) collectExpressionReads(child, state);
		});
		return;
	}

	if (
		node.type === 'ForStatement' ||
		node.type === 'ForInStatement' ||
		node.type === 'ForOfStatement'
	) {
		withShadowedBindings(state, forHeadBindingNames(node), () => {
			for (const child of childNodes(node)) collectExpressionReads(child, state);
		});
		return;
	}

	if (node.type === 'CatchClause') {
		withShadowedBindings(state, bindingNames(node.param as AnyNode | undefined), () => {
			collectExpressionReads(node.body as AnyNode | undefined, state);
		});
		return;
	}

	if (node.type === 'VariableDeclaration') {
		withShadowedBindings(state, declarationBindingNames(node), () => {
			for (const declaration of asNodes(node.declarations)) {
				collectExpressionReads(declaration.init as AnyNode | undefined, state);
			}
		});
		return;
	}

	if (node.type === 'AssignmentExpression') {
		const operator = typeof node.operator === 'string' ? node.operator : '=';
		if (operator !== '=') {
			collectExpressionReads(node.left as AnyNode | undefined, state);
		}
		collectExpressionReads(node.right as AnyNode | undefined, state);
		return;
	}

	if (node.type === 'UpdateExpression') {
		collectExpressionReads(node.argument as AnyNode | undefined, state);
		return;
	}

	if (node.type === 'UnaryExpression' && node.operator === 'delete') {
		collectDeleteComputedPropertyReads(node.argument as AnyNode | undefined, state);
		return;
	}

	if (node.type === 'CallExpression') {
		const callee = node.callee as AnyNode | undefined;
