export type AnyNode = {
	readonly type?: string;
	readonly start?: number;
	readonly end?: number;
	readonly [key: string]: unknown;
};

const ignoredWalkKeys = new Set([
	'closingElement',
	'id',
	'leadingComments',
	'loc',
	'metadata',
	'openingElement',
	'parent',
	'range',
	'trailingComments',
]);

export function walkNode(node: AnyNode | null | undefined, visit: (node: AnyNode) => void): void {
	if (!node || typeof node !== 'object') return;

	visit(node);

	for (const child of childNodes(node)) {
		walkNode(child, visit);
	}
}

export function childNodes(node: AnyNode): AnyNode[] {
	const children: AnyNode[] = [];

	for (const [key, value] of Object.entries(node)) {
		if (ignoredWalkKeys.has(key)) continue;

		if (Array.isArray(value)) {
			for (const item of value) {
				if (isNode(item)) children.push(item);
			}
			continue;
		}

		if (isNode(value)) children.push(value);
	}

	return children;
}

export function asNodes(value: unknown): AnyNode[] {
	return Array.isArray(value) ? value.filter(isNode) : [];
}

export function isNode(value: unknown): value is AnyNode {
	return (
		typeof value === 'object' && value !== null && typeof (value as AnyNode).type === 'string'
	);
}

export function getIdentifierName(node: AnyNode | undefined | null): string | null {
	return typeof node?.name === 'string' ? node.name : null;
}
import type { SourceSpan } from '../artifacts.ts';
import type { AnyNode } from './nodes.ts';

export function expressionSource(node: AnyNode, source: string): string {
	if (typeof node.start !== 'number' || typeof node.end !== 'number') return '';

	return source.slice(node.start, node.end).trim();
}

export function expressionSourceOrFallback(
	node: AnyNode | undefined,
	source: string,
	fallback: string,
): string {
	if (!node) return fallback;

	return expressionSource(node, source) || fallback;
}

export function sourceSpan(node: AnyNode, filename: string): SourceSpan | undefined {
	if (typeof node.start !== 'number' || typeof node.end !== 'number') return undefined;

	return {
		filename,
		start: node.start,
		end: node.end,
	};
}

